/// Every sound the game can make; the files live in `assets/audio/sfx` (generated by `tools/audio`).
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Sound {
    RifleShot,
    MachineGunShot,
    CannonShot,
    HeavyCannonShot,
    HowitzerShot,
    MissileLaunch,
    BulletImpact,
    ShellExplosion,
    VehicleExplosion,
    BuildingCollapse,
    UiClick,
    UiError,
    ConstructionComplete,
    UnitReady,
    BuildingPlaced,
    BaseAlert,
    Credits,
    UnitAcknowledge,
    RepairStarted,
    StructureSold,
    StructureCaptured,
    UnitPromoted,
    FlakShot,
    SniperShot,
}

impl Sound {
    const ALL: [Sound; 24] = [
        Sound::RifleShot,
        Sound::MachineGunShot,
        Sound::CannonShot,
        Sound::HeavyCannonShot,
        Sound::HowitzerShot,
        Sound::MissileLaunch,
        Sound::BulletImpact,
        Sound::ShellExplosion,
        Sound::VehicleExplosion,
        Sound::BuildingCollapse,
        Sound::UiClick,
        Sound::UiError,
        Sound::ConstructionComplete,
        Sound::UnitReady,
        Sound::BuildingPlaced,
        Sound::BaseAlert,
        Sound::Credits,
        Sound::UnitAcknowledge,
        Sound::RepairStarted,
        Sound::StructureSold,
        Sound::StructureCaptured,
        Sound::UnitPromoted,
        Sound::FlakShot,
        Sound::SniperShot,
    ];

    /// File variants; one is picked at random each time so repeats do not sound mechanical.
    fn files(self) -> &'static [&'static str] {
        match self {
            Sound::RifleShot => &["rifle_shot_1", "rifle_shot_2", "rifle_shot_3"],
            Sound::MachineGunShot => &["mg_shot"],
            Sound::CannonShot => &["cannon_shot"],
            Sound::HeavyCannonShot => &["heavy_cannon_shot"],
            Sound::HowitzerShot => &["howitzer_shot"],
            Sound::MissileLaunch => &["missile_launch"],
            Sound::BulletImpact => &["impact_small_1", "impact_small_2"],
            Sound::ShellExplosion => &["explosion_1", "explosion_2"],
            Sound::VehicleExplosion => &["explosion_large"],
            Sound::BuildingCollapse => &["building_collapse"],
            Sound::UiClick => &["ui_click"],
            Sound::UiError => &["ui_error"],
            Sound::ConstructionComplete => &["construction_complete"],
            Sound::UnitReady => &["unit_ready"],
            Sound::BuildingPlaced => &["building_placed"],
            Sound::BaseAlert => &["base_alert"],
            Sound::Credits => &["credits"],
            Sound::UnitAcknowledge => &["unit_acknowledge"],
            Sound::RepairStarted => &["repair_started"],
            Sound::StructureSold => &["structure_sold"],
            Sound::StructureCaptured => &["structure_captured"],
            Sound::UnitPromoted => &["unit_promoted"],
            Sound::FlakShot => &["flak_shot"],
            Sound::SniperShot => &["sniper_shot"],
        }
    }

    /// How many copies may start within one throttle window, so a squad firing together stays readable.
    fn burst_limit(self) -> usize {
        match self {
            Sound::RifleShot | Sound::MachineGunShot | Sound::BulletImpact => 3,
            Sound::CannonShot
            | Sound::HeavyCannonShot
            | Sound::ShellExplosion
            | Sound::MissileLaunch
            | Sound::FlakShot => 2,
            _ => 1,
        }
    }

    fn base_volume(self) -> f32 {
        match self {
            Sound::RifleShot | Sound::MachineGunShot => 0.45,
            Sound::BulletImpact => 0.35,
            Sound::UiClick | Sound::UnitAcknowledge => 0.5,
            _ => 0.8,
        }
    }
}

/// A request from the simulation to make a sound; `position` is `None` for interface sounds heard everywhere.
#[derive(Message, Clone, Copy, Debug)]
pub struct SoundCue {
    pub sound: Sound,
    pub position: Option<Vec3>,
}

impl SoundCue {
    pub fn at(sound: Sound, position: Vec3) -> Self {
        Self {
            sound,
            position: Some(position),
        }
    }

    pub fn interface(sound: Sound) -> Self {
        Self {
            sound,
            position: None,
        }
    }
}

#[derive(Resource)]
pub struct SoundLibrary {
    effects: HashMap<Sound, Vec<Handle<AudioSource>>>,
    menu_theme: Handle<AudioSource>,
    battle_themes: Vec<Handle<AudioSource>>,
    victory: Handle<AudioSource>,
    defeat: Handle<AudioSource>,
}

pub fn load_sounds(mut commands: Commands, asset_server: Res<AssetServer>) {
    let music = |name: &str| asset_server.load(format!("audio/music/{name}.ogg"));
    let effects = Sound::ALL
        .into_iter()
        .map(|sound| {
            let variants = sound
                .files()
                .iter()
                .map(|file| asset_server.load(format!("audio/sfx/{file}.ogg")))
                .collect();
            (sound, variants)
        })
        .collect();
    commands.insert_resource(SoundLibrary {
        effects,
        menu_theme: music("menu_theme"),
        battle_themes: vec![music("battle_1"), music("battle_2")],
        victory: music("victory"),
        defeat: music("defeat"),
    });
}

const THROTTLE_WINDOW_SECS: f32 = 0.12;
/// Battle sounds fade with distance from the camera's focus point and vanish beyond this.
const HEARING_RANGE: f32 = 110.0;
const FULL_VOLUME_RANGE: f32 = 25.0;
const PITCH_VARIATION: f32 = 0.06;

fn distance_attenuation(distance: f32) -> f32 {
    1.0 - ((distance - FULL_VOLUME_RANGE) / (HEARING_RANGE - FULL_VOLUME_RANGE)).clamp(0.0, 1.0)
}

#[derive(Default)]
pub struct Throttle {
    recent: HashMap<Sound, (f32, usize)>,
}

pub fn play_sound_cues(
    mut commands: Commands,
    mut cues: MessageReader<SoundCue>,
    mut throttle: Local<Throttle>,
    time: Res<Time<Real>>,
    library: Option<Res<SoundLibrary>>,
    settings: Res<GameSettings>,
    fog: Option<Res<FogOfWar>>,
    cameras: Query<&RtsCamera>,
) {
    let Some(library) = library else {
        cues.clear();
        return;
    };
    let now = time.elapsed_secs();
    let listener = cameras.single().map(|camera| camera.focus).ok();
    let mut rng = rand::rng();
    for cue in cues.read() {
        let attenuation = match (cue.position, listener) {
            (None, _) => 1.0,
            (Some(position), Some(listener)) => {
                let hidden = fog.as_ref().is_some_and(|fog| !fog.is_visible(position));
                if hidden {
                    0.0
                } else {
                    distance_attenuation(position.xz().distance(listener.xz()))
                }
            }
            (Some(_), None) => 0.0,
        };
        if attenuation <= 0.0 {
            continue;
        }
        let (window_start, played) = throttle.recent.entry(cue.sound).or_insert((now, 0));
        if now - *window_start > THROTTLE_WINDOW_SECS {
            *window_start = now;
            *played = 0;
        }
        if *played >= cue.sound.burst_limit() {
            continue;
        }
        *played += 1;
        let Some(variants) = library.effects.get(&cue.sound).filter(|v| !v.is_empty()) else {
            continue;
        };
        let source = variants[rng.random_range(0..variants.len())].clone();
        let volume = cue.sound.base_volume() * attenuation * settings.effects_volume;
        commands.spawn((
            AudioPlayer(source),
            PlaybackSettings::DESPAWN
                .with_volume(Volume::Linear(volume))
                .with_speed(1.0 + rng.random_range(-PITCH_VARIATION..PITCH_VARIATION)),
        ));
    }
}

/// Unattended capture runs stay silent so they never play sound on the developer's desk.
pub fn apply_master_volume(settings: Res<GameSettings>, mut global: ResMut<GlobalVolume>) {
    if settings.is_changed() {
        let level = if crate::capture::is_capture_run() {
            0.0
        } else {
            settings.master_volume
        };
        global.volume = Volume::Linear(level);
    }
}

/// Clicking any button of the interface gives a short tick.
pub fn click_feedback(
    click: On<PointerClick>,
    buttons: Query<(), With<Hovered>>,
    mut cues: MessageWriter<SoundCue>,
) {
    if buttons.contains(click.entity) && click.button == PointerButton::Primary {
        cues.write(SoundCue::interface(Sound::UiClick));
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum MusicPiece {
    Menu,
    Battle(usize),
    Victory,
    Defeat,
}

#[derive(Component)]
pub struct MusicTrack;

#[derive(Resource, Default)]
pub struct MusicDirector {
    matches_started: usize,
    /// The piece last started; a sting keeps this value after it finishes so it is not replayed.
    current: Option<MusicPiece>,
}

const MUSIC_LEVEL: f32 = 0.6;

fn spawn_music(commands: &mut Commands, library: &SoundLibrary, piece: MusicPiece, volume: f32) {
    let (source, mode) = match piece {
        MusicPiece::Menu => (library.menu_theme.clone(), PlaybackMode::Loop),
        MusicPiece::Battle(index) => (
            library.battle_themes[index % library.battle_themes.len()].clone(),
            PlaybackMode::Loop,
        ),
        MusicPiece::Victory => (library.victory.clone(), PlaybackMode::Despawn),
        MusicPiece::Defeat => (library.defeat.clone(), PlaybackMode::Despawn),
    };
    commands.spawn((
        MusicTrack,
        AudioPlayer(source),
        PlaybackSettings {
            mode,
            volume: Volume::Linear(volume * MUSIC_LEVEL),
            ..default()
        },
    ));
}

/// Picks the music for the current screen: the menu theme, alternating battle themes, or the end-of-match sting.
pub fn direct_music(
    mut commands: Commands,
    state: Res<State<GameState>>,
    outcome: Option<Res<GameOutcome>>,
    library: Option<Res<SoundLibrary>>,
    settings: Res<GameSettings>,
    mut director: ResMut<MusicDirector>,
    tracks: Query<Entity, With<MusicTrack>>,
    mut sinks: Query<&mut AudioSink, With<MusicTrack>>,
) {
    let Some(library) = library else { return };
    let outcome = outcome.map_or(GameOutcome::Ongoing, |outcome| *outcome);
    let wanted = match (state.get(), outcome) {
        (GameState::MainMenu, _) => Some(MusicPiece::Menu),
        (GameState::Playing, GameOutcome::Victory) => Some(MusicPiece::Victory),
        (GameState::Playing, GameOutcome::Defeat) => Some(MusicPiece::Defeat),
        (GameState::Playing, GameOutcome::Ongoing) | (GameState::Replay, _) => {
            Some(MusicPiece::Battle(director.matches_started))
        }
        (GameState::Booting | GameState::Restarting, _) => None,
    };
    if wanted != director.current {
        for track in &tracks {
            commands.entity(track).despawn();
        }
        if let Some(piece) = wanted {
            spawn_music(&mut commands, &library, piece, settings.music_volume);
        }
        director.current = wanted;
    }
    if settings.is_changed() {
        for mut sink in &mut sinks {
            sink.set_volume(Volume::Linear(settings.music_volume * MUSIC_LEVEL));
        }
    }
}

pub fn count_match_start(mut director: ResMut<MusicDirector>) {
    director.matches_started += 1;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_sound_has_its_files() {
        let sfx = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("assets/audio/sfx");
        for sound in Sound::ALL {
            for file in sound.files() {
                let path = sfx.join(format!("{file}.ogg"));
                assert!(path.is_file(), "{sound:?} is missing {}", path.display());
            }
        }
    }
}
